<script setup lang="ts">
import {computed,nextTick,onMounted,onBeforeUnmount,ref,watch} from 'vue';import {Check,ChevronDown,Search} from 'lucide-vue-next';
const props=withDefaults(defineProps<{value?:string;onChange?:(value:string)=>void;options:any[];placeholder?:string;searchable?:boolean;align?:string;className?:string;buttonClassName?:string;panelWidth?:string}>(),{placeholder:'請選擇',align:'left',panelWidth:'w-56'});
const open=ref(false),query=ref(''),active=ref(-1),root=ref<HTMLElement>(),search=ref<HTMLInputElement>(),button=ref<HTMLButtonElement>();
const canSearch=computed(()=>props.searchable??props.options.length>12),selected=computed(()=>props.options.find(o=>o.value===props.value)),filtered=computed(()=>props.options.filter(o=>o.label.toLowerCase().includes(query.value.trim().toLowerCase())));
function pick(v:string){props.onChange?.(v);open.value=false;button.value?.focus();}
function key(e:KeyboardEvent){if(e.key==='Escape'){open.value=false;button.value?.focus();}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();open.value=true;active.value=Math.max(0,Math.min(filtered.value.length-1,active.value+(e.key==='ArrowDown'?1:-1)));}else if(e.key==='Enter'&&active.value>=0&&filtered.value[active.value]){e.preventDefault();pick(filtered.value[active.value].value);}}
function outside(e:Event){if(!root.value?.contains(e.target as Node))open.value=false;}
watch(open,async value=>{if(value){await nextTick();if(canSearch.value)search.value?.focus();}else{query.value='';active.value=-1;}});
onMounted(()=>document.addEventListener('pointerdown',outside));onBeforeUnmount(()=>document.removeEventListener('pointerdown',outside));
</script><template><div ref="root" :class="['relative',className]" @keydown="key"><button ref="button" type="button" @click="open=!open" aria-haspopup="listbox" :aria-expanded="open" :class="['inline-flex items-center gap-1 rounded-token-md border border-line px-2 py-0.5 text-token-xs text-ink-muted transition-colors duration-fast hover:border-ink-faint',buttonClassName]"><span class="truncate">{{selected?.label??placeholder}}</span><ChevronDown :size="12" class="shrink-0 text-ink-faint"/></button><div v-if="open" role="listbox" :class="['absolute z-50 mt-1 overflow-hidden rounded-token-md border border-line-soft bg-paper shadow-token-sm',panelWidth,align==='right'?'right-0':'left-0']"><div v-if="canSearch" class="relative border-b border-line-soft"><Search :size="13" class="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2 text-ink-faint"/><input ref="search" type="search" v-model="query" @input="active=-1" placeholder="搜尋…" class="w-full bg-transparent py-2 pl-8 pr-2 text-token-xs text-ink placeholder:text-ink-faint focus:outline-none"/></div><ul class="max-h-60 overflow-y-auto py-1"><li v-if="!filtered.length" class="px-3 py-2 text-token-xs text-ink-faint">無相符</li><li v-for="(o,i) in filtered" :key="o.value"><button type="button" role="option" :aria-selected="o.value===value" @mouseenter="active=i" @click="pick(o.value)" :class="['flex w-full items-center gap-2 px-3 py-1.5 text-left text-token-xs transition-colors duration-fast',i===active?'bg-surface-raised':'',o.value===value?'text-accent':'text-ink-muted']"><Check :size="12" :class="['shrink-0',o.value===value?'opacity-100':'opacity-0']"/><span class="min-w-0 flex-1 truncate">{{o.label}}</span><span v-if="o.hint" class="shrink-0 tabular-nums text-ink-faint">{{o.hint}}</span></button></li></ul></div></div></template>
